css:
/* Těžké nadpisy verzálkami */
h1, h2, h3, .mb-brand { text-transform: uppercase; letter-spacing: -0.02em; }
/* Tenké černé linky místo stínů */
.card, .mb-panel { border: 1px solid var(--color-white); box-shadow: none !important; }
.btn { border: 1px solid var(--color-white); text-transform: uppercase; letter-spacing: 0.02em; }
.btn:not(:disabled):active { transform: none; background-image: linear-gradient(rgb(0 0 0 / 0.08), rgb(0 0 0 / 0.08)); }
.input { border: 1px solid var(--color-white); }
/* Strojopisné popisky */
.mb-label, .chip { font-family: 'IBM Plex Mono', ui-monospace, monospace; text-transform: uppercase; letter-spacing: 0.18em; font-weight: 500; }
.chip { border: 1px solid currentColor; }
/* Zvýraznění černou, žádná barevná záře */
.mb-accent-scope { --mb-accent: var(--color-white) !important; }
.mb-glow { display: none !important; }
.mb-progress { background: var(--color-pink) !important; outline: 1px solid var(--color-white); }
/* Čtvercový obal místo gramofonové desky */
.mb-vinyl-record { background: none !important; box-shadow: none !important; border-radius: 0 !important; animation: none !important; }
.mb-vinyl-cover { inset: 0 !important; border-radius: 0 !important; box-shadow: 0 0 0 1px var(--color-white) !important; }
.mb-vinyl-hole, .mb-vinyl-arm, .mb-disc-hole { display: none !important; }
.mb-disc { border-radius: 0 !important; animation: none !important; box-shadow: 0 0 0 1px var(--color-white) !important; }

effects.css:
.mb-label.mb-live::before { content: ''; display: inline-block; width: 0.75em; height: 0.75em; margin-right: 0.6em; border-radius: 999px; border: 1.5px solid var(--color-white); background: var(--color-pink); vertical-align: -0.05em; animation: mb-pulse 1.6s ease-in-out infinite; }
.mb-label.mb-live > svg, .mb-label.mb-live > .mb-eq { display: none; }
@keyframes mb-pulse { 0%, 100% { box-shadow: 0 0 0 0 rgb(212 255 58 / 0.9); } 50% { box-shadow: 0 0 0 0.45em rgb(212 255 58 / 0); } }
